package org.example.service;

import org.example.entity.*;
import org.example.mapper.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.Collectors;
import static org.example.service.PermissionService.*;

@Service
public class PermissionManagementService {
    public record RoleChange(String code,String name,List<String> permissions,Map<String,Object> scopes,Boolean enabled,Long version,Long revision,String reason) { }
    public record UserChange(String mode,List<String> roles,Map<String,Boolean> overrides,Map<String,Object> scopes,Long version,Long revision,String reason) { }
    public record ExpertAccount(Long userId,String nickName,String userName,String email,String reason) { }
    private final PermissionService access;private final JdbcTemplate jdbc;private final SysMapper users;private final AdminManagementMapper logs;
    public PermissionManagementService(PermissionService access,JdbcTemplate jdbc,SysMapper users,AdminManagementMapper logs){this.access=access;this.jdbc=jdbc;this.users=users;this.logs=logs;}
    public Map<String,Object> catalog(Long actor){access.requireAdmin(actor);Map<String,Object> result=new LinkedHashMap<>();result.put("modules",PermissionCatalog.MODULES);result.put("permissions",PermissionCatalog.ACTIONS);result.put("roles",access.roles());result.put("revision",access.revision());return result;}
    public Map<String,Object> options(Long actor){access.requireAdmin(actor);return Map.of("departments",jdbc.queryForList("SELECT dept_id id,dept_name name,status FROM sys_dept WHERE COALESCE(is_delete,0)=0 ORDER BY dept_id"),
        "tasks",jdbc.queryForList("SELECT task_id id,parent_id parentId,task_code code,task_name name,phase year,level,dept_id deptId FROM biz_task WHERE COALESCE(is_delete,0)=0 ORDER BY level,task_code,task_id"),
        "performance",jdbc.queryForList("SELECT perf_id id,perf_code code,perf_name name,dept_id deptId FROM biz_performance WHERE COALESCE(is_delete,0)=0 AND LENGTH(ancestors)-LENGTH(REPLACE(ancestors,',',''))>=2 ORDER BY perf_code,perf_id"),
        "achievements",jdbc.queryForList("SELECT ach_id id,ach_name name,dept_id deptId FROM biz_achievement WHERE COALESCE(is_delete,0)=0 ORDER BY ach_id"),
        "core",jdbc.queryForList("SELECT indicator_id id,indicator_code code FROM biz_core_indicator ORDER BY sort_order"));}
    public Map<String,Object> optionStructure(Long actor){access.requireAdmin(actor);return Map.of("departments",jdbc.queryForList("SELECT dept_id id,dept_name name,status FROM sys_dept WHERE COALESCE(is_delete,0)=0 ORDER BY dept_id"),"core",jdbc.queryForList("SELECT indicator_id id,indicator_code code FROM biz_core_indicator ORDER BY sort_order"),"tasks",List.of(),"performance",List.of(),"achievements",List.of());}
    public Map<String,Object> configuration(Long id,Long actor){access.requireAdmin(actor);existing(id);var policy=access.policy(id);Map<String,Object> result=new LinkedHashMap<>();result.put("userId",id);result.put("policy",policy);result.put("revision",access.revision());result.put("effective",effective(id,policy,Map.of()));return result;}
    private Map<String,Object> effective(Long id,PermissionService.Policy policy,Map<String,PermissionCatalog.Role> replacement){
        if(!"1".equals(existing(id).getStatus()))return Map.of("inactive",true,"permissions",List.of(),"taskCount",0,"notice","账号已停用，启用后按配置生效");
        var state=access.evaluate(id,policy,replacement);Map<String,Object> result=new LinkedHashMap<>();result.put("permissions",state.permissions());result.put("roles",state.roles());result.put("taskCount",access.taskIds(state,null).size());result.put("taskIds",access.taskIds(state,null));
        Map<String,Object> duties=new LinkedHashMap<>();duties.put("tasks",jdbc.queryForList("SELECT task_id id,task_name name,phase year,leader_id,auditor_id,principal_id FROM biz_task WHERE level=3 AND COALESCE(is_delete,0)=0 AND (leader_id=? OR auditor_id=? OR principal_id=?) ORDER BY task_id",id,id,id));
        duties.put("performance",jdbc.queryForList("SELECT perf_id id,perf_name name,leader_id,auditor_id,principal_id FROM biz_performance WHERE COALESCE(is_delete,0)=0 AND (leader_id=? OR auditor_id=? OR principal_id=?) ORDER BY perf_id",id,id,id));result.put("duties",duties);result.put("notice","功能授权不分配业务职责；审核只可处理本人待办，填报仍核验责任关系及年度资格。");return result;
    }
    public Map<String,Object> previewUser(Long id,UserChange body,Long actor){access.requireAdmin(actor);existing(id);PermissionService.Policy after=validateUser(id,body);var before=access.policy(id);checkVersion(before.version(),body.version());checkRevision(body.revision());List<Map<String,Object>> blocked=lostPending(id,before,after,Map.of());
        return preview(effective(id,before,Map.of()),effective(id,after,Map.of()),blocked,access.revision());}
    @Transactional(rollbackFor=Exception.class,isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
    public Object saveUser(Long id,UserChange body,Long actor){access.requireAdmin(actor);access.lockChange();if(logs.userForUpdate(id)==null)throw new AdminManagementException(404,"账号不存在");PermissionService.Policy after=validateUser(id,body);var before=access.policy(id);checkVersion(before.version(),body.version());checkRevision(body.revision());reason(body.reason());
        var blocked=lostPending(id,before,after,Map.of());block(blocked);
        jdbc.update("INSERT INTO sys_user_permission(user_id,access_mode,permissions_json,scopes_json,version,update_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE access_mode=VALUES(access_mode),permissions_json=VALUES(permissions_json),scopes_json=VALUES(scopes_json),version=VALUES(version),update_by=VALUES(update_by),update_time=NOW(3)",id,after.mode(),access.write(after.overrides()),access.write(after.scopes()),before.version()+1,actor);
        jdbc.update("DELETE FROM sys_user_permission_role WHERE user_id=?",id);for(String role:after.roles())jdbc.update("INSERT INTO sys_user_permission_role(user_id,role_code) VALUES(?,?)",id,role);
        access.advance();log("USER_POLICY","USER",str(id),existing(id).getNickName(),actor,body.reason(),before,access.policy(id));return configuration(id,actor);
    }
    public Map<String,Object> previewRole(RoleChange body,Long actor){access.requireAdmin(actor);var role=validateRole(body);var old=access.roles().stream().filter(r->r.code().equals(role.code())).findFirst().orElse(null);checkVersion(old==null?0:old.version(),body.version());checkRevision(body.revision());
        List<Map<String,Object>> impacts=roleImpacts(role);return Map.of("before",old==null?Map.of():old,"after",role,"impacts",impacts,"blocked",impacts.stream().flatMap(r->((List<?>)r.get("blocked")).stream()).toList(),"revision",access.revision());}
    @Transactional(rollbackFor=Exception.class,isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
    public Object saveRole(RoleChange body,Long actor){access.requireAdmin(actor);access.lockChange();var role=validateRole(body);var old=access.roles().stream().filter(r->r.code().equals(role.code())).findFirst().orElse(null);checkVersion(old==null?0:old.version(),body.version());checkRevision(body.revision());reason(body.reason());
        for(var impact:roleImpacts(role))block((List<?>)impact.get("blocked"));
        jdbc.update("INSERT INTO sys_permission_role(role_code,role_name,permissions_json,scopes_json,enabled,version,update_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE role_name=VALUES(role_name),permissions_json=VALUES(permissions_json),scopes_json=VALUES(scopes_json),enabled=VALUES(enabled),version=VALUES(version),update_by=VALUES(update_by),update_time=NOW(3)",role.code(),role.name(),access.write(role.permissions()),access.write(role.scopes()),role.enabled()?1:0,(old==null?0:old.version())+1,actor);
        access.advance();log("ROLE_UPDATE","ROLE",role.code(),role.name(),actor,body.reason(),old,role);return catalog(actor);
    }
    @Transactional(rollbackFor=Exception.class,isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
    public Object deleteRole(String code,Long version,Long revision,String reason,Long actor){access.requireAdmin(actor);access.lockChange();if(PermissionCatalog.BUILTINS.containsKey(code))throw new AdminManagementException(409,"内置角色不可删除，可以调整或停用非管理员模板");
        var role=access.roles().stream().filter(r->r.code().equals(code)).findFirst().orElseThrow(()->new AdminManagementException(404,"角色不存在"));checkVersion(role.version(),version);checkRevision(revision);reason(reason);
        if(jdbc.queryForObject("SELECT COUNT(*) FROM sys_user_permission_role WHERE role_code=?",Integer.class,code)>0)throw new AdminManagementException(409,"角色仍分配给账号，请先调整这些账号");jdbc.update("DELETE FROM sys_permission_role WHERE role_code=?",code);access.advance();log("ROLE_DELETE","ROLE",code,role.name(),actor,reason,role,null);return Map.of("message","角色已删除");}
    private List<Map<String,Object>> roleImpacts(PermissionCatalog.Role role){List<Map<String,Object>> result=new ArrayList<>();for(SysUser user:users.getAllUsers())if("1".equals(user.getStatus())&&!Integer.valueOf(1).equals(user.getIsDelete())&&!"0".equals(user.getRole())){
        var current=access.state(user.getUserId());boolean assigned=current.roles().stream().anyMatch(r->r.code().equals(role.code()))||current.policy().roles().contains(role.code());if(!assigned)continue;
        var after=access.evaluate(user.getUserId(),current.policy(),Map.of(role.code(),role));Map<String,Object> impact=new LinkedHashMap<>();impact.put("userId",user.getUserId());impact.put("name",user.getNickName());impact.put("beforePermissions",current.permissions());impact.put("afterPermissions",after.permissions());impact.put("beforeTasks",access.taskIds(current,null).size());impact.put("afterTasks",access.taskIds(after,null).size());impact.put("blocked",lostPending(user.getUserId(),current.policy(),current.policy(),Map.of(role.code(),role)));result.add(impact);
    }return result;}
    public void validateCurrentPending(Long id){if(!"1".equals(existing(id).getStatus()))return;var state=access.state(id);var invalid=pending(id).stream().filter(p->!canHandle(state,p)).toList();block(invalid);}
    public Map<String,Map<String,Object>> pendingSnapshot(){
        String objects="SELECT 'tasks' domain,s.sub_id id,s.task_id objectId,t.phase year,s.flow_status stage,s.current_handler_id handler,t.dept_id department,t.leader_id owner,t.auditor_id auditor,t.principal_id principal FROM biz_material_submission s JOIN biz_task t ON t.task_id=s.task_id WHERE s.flow_status IN(10,20,30) AND COALESCE(s.is_delete,0)=0 "
            +"UNION ALL SELECT 'performance',s.sub_id,s.perf_id,s.year,s.flow_status,s.current_handler_id,p.dept_id,p.leader_id,p.auditor_id,p.principal_id FROM biz_performance_submission s JOIN biz_performance p ON p.perf_id=s.perf_id WHERE s.flow_status IN(10,20) AND COALESCE(s.is_delete,0)=0 "
            +"UNION ALL SELECT 'achievements',a.ach_id,a.ach_id,YEAR(a.got_time),10,a.current_handler_id,a.dept_id,a.create_by,NULL,NULL FROM biz_achievement a WHERE a.audit_status=10 AND COALESCE(a.is_delete,0)=0 "
            +"UNION ALL SELECT 'core',r.report_id,r.indicator_id,r.record_year,r.flow_status,r.current_handler_id,NULL,r.submit_by,NULL,r.principal_id FROM biz_core_report r JOIN biz_core_indicator c ON c.indicator_id=r.indicator_id AND BINARY c.indicator_code=BINARY r.performance_code WHERE r.flow_status IN(10,20)";
        Map<String,Map<String,Object>> result=new LinkedHashMap<>();
        for(var row:jdbc.queryForList("SELECT q.*,u.role handlerRole,u.status handlerStatus,u.dept_id handlerDepartment,u.is_delete handlerDeleted,COALESCE(l.version,0) leadershipVersion FROM ("+objects+") q LEFT JOIN sys_user u ON u.user_id=q.handler LEFT JOIN sys_leadership_access l ON l.user_id=q.handler")){
            if(row.get("handler")==null)continue;row.put("archive",str(row.get("domain")).equals("tasks")?number(row.get("stage"))==30:Set.of("performance","core").contains(str(row.get("domain")))&&number(row.get("stage"))==20);
            result.put(str(row.get("domain"))+":"+str(row.get("id")),row);
        }return result;
    }
    public void validateChangedPending(Map<String,Map<String,Object>> before){for(var e:pendingSnapshot().entrySet())if(!Objects.equals(before.get(e.getKey()),e.getValue())){var row=e.getValue();Long handler=number(row.get("handler"));if(!canHandle(access.state(handler),row))throw new AdminManagementException(409,"操作将产生无处理权限的待办，请先调整审核人或权限："+handler);}}
    private List<Map<String,Object>> lostPending(Long id,PermissionService.Policy before,PermissionService.Policy after,Map<String,PermissionCatalog.Role> replacement){if(!"1".equals(existing(id).getStatus()))return List.of();var a=access.evaluate(id,before,Map.of());var b=access.evaluate(id,after,replacement);return pending(id).stream().filter(p->canHandle(a,p)&&!canHandle(b,p)).toList();}
    public void requireHandler(Long id,String domain,Long object,Integer year,int stage){var state=access.state(id);boolean archive=stage==20&&Set.of("core","performance").contains(domain)||stage==30&&domain.equals("tasks");if(!archiveEligible(state,domain,archive)||!state.permissions().contains(domain+(archive?".archive":".audit"))||!access.canRead(state,domain,object,year))throw new AdminManagementException(409,"拟定处理人未获准处理此业务，请先调整权限或移交："+id);}
    private boolean canHandle(PermissionService.State state,Map<String,Object> row){String domain=str(row.get("domain"));String action=Boolean.TRUE.equals(row.get("archive"))?"archive":"audit";return archiveEligible(state,domain,action.equals("archive"))&&state.permissions().contains(domain+"."+action)&&access.canRead(state,domain,number(row.get("objectId")),row.get("year")==null?null:(int)number(row.get("year")));}
    private boolean archiveEligible(PermissionService.State state,String domain,boolean archive){return !archive||state.admin()||!domain.equals("core")&&Objects.equals(state.userId(),110228L);}
    private List<Map<String,Object>> pending(Long id){List<Map<String,Object>> result=new ArrayList<>();
        for(var r:jdbc.queryForList("SELECT sub_id id,task_id objectId,flow_status FROM biz_material_submission WHERE current_handler_id=? AND flow_status IN(10,20,30) AND COALESCE(is_delete,0)=0",id)){r.put("domain","tasks");r.put("archive",number(r.get("flow_status"))==30);result.add(r);}
        for(var r:jdbc.queryForList("SELECT sub_id id,perf_id objectId,year,flow_status FROM biz_performance_submission WHERE current_handler_id=? AND flow_status IN(10,20) AND COALESCE(is_delete,0)=0",id)){r.put("domain","performance");r.put("archive",number(r.get("flow_status"))==20);result.add(r);}
        for(var r:jdbc.queryForList("SELECT ach_id id,ach_id objectId FROM biz_achievement WHERE current_handler_id=? AND audit_status=10 AND COALESCE(is_delete,0)=0",id)){r.put("domain","achievements");r.put("archive",false);result.add(r);}
        for(var r:jdbc.queryForList("SELECT r.report_id id,r.indicator_id objectId,r.record_year year,r.flow_status FROM biz_core_report r JOIN biz_core_indicator c ON c.indicator_id=r.indicator_id AND BINARY c.indicator_code=BINARY r.performance_code WHERE r.current_handler_id=? AND r.flow_status IN(10,20)",id)){r.put("domain","core");r.put("archive",number(r.get("flow_status"))==20);result.add(r);}return result;
    }
    @Transactional(rollbackFor=Exception.class,isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
    public Object createExpert(ExpertAccount body,Long actor){access.requireAdmin(actor);access.lockChange();if(body==null||body.userId()==null||body.userId()<=0||body.nickName()==null||body.nickName().isBlank()||body.nickName().length()>100)throw new AdminManagementException(400,"请填写有效数字账号编号及姓名");String username=body.userName()==null||body.userName().isBlank()?"expert_"+body.userId():body.userName().trim();if(username.length()>100||users.getUserById(body.userId())!=null||users.getUserByName(username)!=null)throw new AdminManagementException(409,"账号编号或账号名称已被使用");
        if(body.email()!=null&&body.email().length()>50)throw new AdminManagementException(400,"邮箱最多50字");SysUser u=new SysUser();u.setUserId(body.userId());u.setNickName(body.nickName().trim());u.setUserName(username);u.setEmail(body.email());u.setRole("1");u.setStatus("1");u.setIsDelete(0);u.setPassword(str(body.userId()));u.setForcePasswordChange(1);u.setCreateTime(new Date());u.setUpdateTime(u.getCreateTime());users.addUser(u);
        jdbc.update("INSERT INTO sys_user_permission(user_id,access_mode,permissions_json,scopes_json,version,update_by) VALUES(?,'CUSTOM','{}','{}',1,?)",u.getUserId(),actor);jdbc.update("INSERT INTO sys_user_permission_role(user_id,role_code) VALUES(?,'EXPERT')",u.getUserId());access.advance();
        log("EXPERT_CREATE","USER",str(u.getUserId()),u.getNickName(),actor,"新增专家账号",null,Map.of("userId",u.getUserId(),"name",u.getNickName(),"template","EXPERT","forcePasswordChange",true));return Map.of("userId",u.getUserId(),"message","专家账号已创建，首次登录必须修改密码");}
    private PermissionService.Policy validateUser(Long id,UserChange body){access.requireInstalled();if(access.admin(id))throw new AdminManagementException(409,"管理员权限固定为全权限，需先在账号管理中调整身份");if(body==null||!Set.of("LEGACY","CUSTOM").contains(body.mode()))throw new AdminManagementException(400,"请选择沿用业务资格或自定义角色");List<String> roles=body.roles()==null?List.of():body.roles();if(roles.stream().anyMatch(Objects::isNull)||new HashSet<>(roles).size()!=roles.size())throw new AdminManagementException(400,"角色不能重复");Map<String,PermissionCatalog.Role> definitions=access.roles().stream().collect(Collectors.toMap(PermissionCatalog.Role::code,r->r));for(String code:roles)if(code.equals("ADMIN")||!definitions.containsKey(code)||!definitions.get(code).enabled())throw new AdminManagementException(400,"请选择有效非管理员角色");Map<String,Boolean> overrides=body.overrides()==null?Map.of():body.overrides();for(var e:overrides.entrySet())if(!PermissionCatalog.ACTIONS.containsKey(e.getKey())||e.getValue()==null)throw new AdminManagementException(400,"个人权限项不正确");return new PermissionService.Policy(body.mode(),new LinkedHashMap<>(overrides),normalizeScopes(body.scopes()),List.copyOf(roles),body.version()==null?0:body.version());}
    private PermissionCatalog.Role validateRole(RoleChange body){access.requireInstalled();if(body==null||body.code()==null||!body.code().matches("[A-Z][A-Z0-9_]{1,63}")||body.code().equals("ADMIN")||body.name()==null||body.name().isBlank()||body.name().length()>100||body.permissions()==null||body.enabled()==null)throw new AdminManagementException(400,"请填写有效角色代码、名称及功能权限；管理员模板不可修改");if(new HashSet<>(body.permissions()).size()!=body.permissions().size()||!PermissionCatalog.ACTIONS.keySet().containsAll(body.permissions()))throw new AdminManagementException(400,"角色权限项无效或重复");var base=PermissionCatalog.BUILTINS.get(body.code());return new PermissionCatalog.Role(body.code(),body.name().trim(),List.copyOf(body.permissions()),normalizeScopes(body.scopes()),base!=null,base!=null&&base.dynamic(),body.enabled(),body.version()==null?0:body.version());}
    @SuppressWarnings("unchecked")
    private Map<String,Object> normalizeScopes(Map<String,Object> scopes){if(scopes==null)return Map.of();Map<String,Object> result=new LinkedHashMap<>();for(var entry:scopes.entrySet()){
        String domain=entry.getKey();if(!Set.of("tasks","performance","achievements","core","records","budget").contains(domain)||!(entry.getValue() instanceof Map<?,?> raw))throw new AdminManagementException(400,"数据范围模块不正确");Map<String,Object> r=(Map<String,Object>)raw;String mode=str(r.get("mode"));if(!Set.of("NONE","ALL","BUSINESS","OWN","CUSTOM","LEADERSHIP").contains(mode)||!Set.of("mode","years","departments","directories","items").containsAll(r.keySet()))throw new AdminManagementException(400,"数据范围类型或字段不正确");
        if(domain.equals("budget")&&!Set.of("ALL","NONE").contains(mode)||domain.equals("core")&&!Set.of("ALL","NONE","CUSTOM").contains(mode))throw new AdminManagementException(400,"该模块不支持此范围类型");Map<String,Object> clean=new LinkedHashMap<>();clean.put("mode",mode);for(String field:List.of("years","departments","directories","items")){Object value=r.get(field);if(value==null)continue;if(!(value instanceof List<?> list)||list.size()>5000)throw new AdminManagementException(400,"范围列表格式或数量不正确");List<Long> values=new ArrayList<>();for(Object item:list){if(!(item instanceof Number)||!item.toString().matches("[0-9]+")||number(item)<=0)throw new AdminManagementException(400,"范围编号必须是正整数");values.add(number(item));}if(new HashSet<>(values).size()!=values.size())throw new AdminManagementException(400,"范围编号不可重复");if(field.equals("years")&&values.stream().anyMatch(y->y<2025||y>2029))throw new AdminManagementException(400,"年度范围为2025—2029年");if(!field.equals("years")&&!values.isEmpty()&&!mode.equals("CUSTOM"))throw new AdminManagementException(400,"仅组合范围可以选择部门、目录或记录");if(field.equals("directories")&&!values.isEmpty()&&!domain.equals("tasks"))throw new AdminManagementException(400,"只有任务支持目录范围");if(domain.equals("core")&&field.equals("departments")&&!values.isEmpty())throw new AdminManagementException(400,"核心指标请按指标选择范围");if(domain.equals("records")&&field.equals("items")&&!values.isEmpty())throw new AdminManagementException(400,"纪实请按本人、部门或全校已提交记录选择");validateScopeIds(domain,field,values);clean.put(field,values);}result.put(domain,clean);
    }return result;}
    private void validateScopeIds(String domain,String field,List<Long> values){if(field.equals("years"))return;String sql=switch(field){case "departments"->"SELECT COUNT(*) FROM sys_dept WHERE dept_id=? AND status='0' AND COALESCE(is_delete,0)=0";case "directories"->"SELECT COUNT(*) FROM biz_task WHERE task_id=? AND level IN(1,2) AND COALESCE(is_delete,0)=0";default->switch(domain){case "tasks"->"SELECT COUNT(*) FROM biz_task WHERE task_id=? AND level=3 AND COALESCE(is_delete,0)=0";case "performance"->"SELECT COUNT(*) FROM biz_performance WHERE perf_id=? AND COALESCE(is_delete,0)=0";case "achievements"->"SELECT COUNT(*) FROM biz_achievement WHERE ach_id=? AND COALESCE(is_delete,0)=0";case "core"->"SELECT COUNT(*) FROM biz_core_indicator WHERE indicator_id=?";default->null;};};if(sql==null&&!values.isEmpty())throw new AdminManagementException(400,"该模块不支持逐条范围");for(Long id:values)if(jdbc.queryForObject(sql,Integer.class,id)!=1)throw new AdminManagementException(400,"范围中包含不存在、停用或已删除的记录："+id);}
    private SysUser existing(Long id){SysUser u=id==null?null:users.getUserById(id);if(u==null||Integer.valueOf(1).equals(u.getIsDelete()))throw new AdminManagementException(404,"账号不存在");return u;}
    private Map<String,Object> preview(Object before,Object after,List<?> blocked,long revision){return Map.of("before",before,"after",after,"blocked",blocked,"revision",revision);}
    private void reason(String value){if(value==null||value.isBlank()||value.length()>500)throw new AdminManagementException(400,"请填写变更原因，最多500字");}
    private void checkVersion(long before,Long expected){if(expected==null||before!=expected)throw new AdminManagementException(409,"配置已被修改，请重新加载");}
    private void checkRevision(Long expected){if(expected==null||access.revision()!=expected)throw new AdminManagementException(409,"权限体系已有变化，请重新加载并预览");}
    private void block(List<?> blocked){if(!blocked.isEmpty())throw new AdminManagementException(409,"变更会导致 "+blocked.size()+" 条现有待办无法处理，请先移交后再调整权限");}
    private void log(String action,String type,String id,String name,Long actor,String reason,Object before,Object after){AdminOperationLog entry=new AdminOperationLog();entry.setModule("PERMISSION");entry.setAction(action);entry.setTargetType(type);entry.setTargetId(id);entry.setTargetName(name);entry.setOperatorId(actor);entry.setReason(reason);entry.setBeforeJson(access.write(before));entry.setAfterJson(access.write(after));entry.setCreateTime(new Date());logs.insertOperation(entry);}
}
